package com.example.nhom33.controller;

import android.os.Bundle;
import android.view.View;
import android.widget.ImageButton;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.nhom33.adapter.Admin_FoodList_Adapter;
import com.example.nhom33.Database.FoodDB;
import com.example.nhom33.DataEntity.FoodsEntity;
import com.example.nhom33.R;
import com.example.nhom33.db.item_food;

import java.util.ArrayList;
import java.util.List;

public class Admin_MyFoodList extends AppCompatActivity {

    RecyclerView recyclerView;
    List<item_food> itemList;
    Admin_FoodList_Adapter myAdapter;

    ImageButton btn_back;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.admin_my_food_list);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        btn_back = findViewById(R.id.btn_back);
        btn_back.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                finish();
            }
        });

        recyclerView = findViewById(R.id.recyclerView);
        itemList = new ArrayList<>();

        LinearLayoutManager layoutManager = new LinearLayoutManager(this);
        recyclerView.setLayoutManager(layoutManager);

        myAdapter = new Admin_FoodList_Adapter(itemList);
        recyclerView.setAdapter(myAdapter);

        // Fetch dữ liệu từ Room Database
        loadFoodsFromDatabase();
    }
}

package com.example.nhom33.controller;

import android.os.Bundle;
import android.view.View;
import android.widget.ImageButton;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.nhom33.adapter.Admin_FoodList_Adapter;
import com.example.nhom33.Database.FoodDB;
import com.example.nhom33.DataEntity.FoodsEntity;
import com.example.nhom33.R;
import com.example.nhom33.db.item_food;

import java.util.ArrayList;
import java.util.List;

public class Admin_MyFoodList extends AppCompatActivity {

    RecyclerView recyclerView;
    List<item_food> itemList;
    Admin_FoodList_Adapter myAdapter;

    ImageButton btn_back;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.admin_my_food_list);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        btn_back = findViewById(R.id.btn_back);
        btn_back.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                finish();
            }
        });

        recyclerView = findViewById(R.id.recyclerView);
        itemList = new ArrayList<>();

        LinearLayoutManager layoutManager = new LinearLayoutManager(this);
        recyclerView.setLayoutManager(layoutManager);

        myAdapter = new Admin_FoodList_Adapter(itemList);
        recyclerView.setAdapter(myAdapter);

        // Fetch dữ liệu từ Room Database
        loadFoodsFromDatabase();
    }

    private void loadFoodsFromDatabase() {
        // Lấy dữ liệu từ database trên background thread
        new Thread(() -> {
            FoodDB db = FoodDB.getInstance(this);
            List<FoodsEntity> foodsEntities = db.foodsDAO().getAllFoods();

            // Chuyển đổi danh sách FoodsEntity sang item_food
            List<item_food> foods = new ArrayList<>();
            for (FoodsEntity entity : foodsEntities) {
                String priceFormatted = String.format("%.0f VND", entity.getPrice());
                item_food item = new item_food(
                        R.drawable.pizza_img, // Drawable mặc định (có thể cập nhật dựa trên imageUrl)
                        entity.getFoodName(),
                        priceFormatted,
                        entity.getMealType()
                );
                foods.add(item);
            }

            // Cập nhật RecyclerView trên UI thread
            runOnUiThread(() -> {
                itemList.clear();
                itemList.addAll(foods);
                myAdapter.notifyDataSetChanged();
            });
        }).start();
    }
}

package com.example.nhom33.Database;

import android.content.Context;

import androidx.room.Database;
import androidx.room.Room;
import androidx.room.RoomDatabase;

import com.example.nhom33.DAO.FoodsDAO;
import com.example.nhom33.DataEntity.CategoriesEntity;
import com.example.nhom33.DataEntity.FoodsEntity;
import com.example.nhom33.DataEntity.UsersEntity;

@Database(entities = {
        FoodsEntity.class,
        CategoriesEntity.class,
        UsersEntity.class
}, version = 1)
public abstract class FoodDB extends RoomDatabase {
    private static final String DB_NAME = "qldoan.db";
    private static FoodDB instance;

    public static synchronized FoodDB getInstance(Context context) {
        if (instance == null) {
            instance = Room.databaseBuilder(context.getApplicationContext(),
                            FoodDB.class, DB_NAME)
                    .allowMainThreadQueries()
                    .fallbackToDestructiveMigration() // Added to handle schema changes during development
                    .build();
        }
        return instance;
    }

    public abstract FoodsDAO foodsDAO();
}

package com.example.nhom33.Database;

import android.content.Context;

import androidx.room.Database;
import androidx.room.Room;
import androidx.room.RoomDatabase;

import com.example.nhom33.DAO.FoodsDAO;
import com.example.nhom33.DataEntity.CategoriesEntity;
import com.example.nhom33.DataEntity.FoodsEntity;
import com.example.nhom33.DataEntity.UsersEntity;

@Database(entities = {
        FoodsEntity.class,
        CategoriesEntity.class,
        UsersEntity.class
}, version = 1)
public abstract class FoodDB extends RoomDatabase {
    private static final String DB_NAME = "qldoan.db";
    private static FoodDB instance;

    public static synchronized FoodDB getInstance(Context context) {
        if (instance == null) {
            instance = Room.databaseBuilder(context.getApplicationContext(),
                            FoodDB.class, DB_NAME)
                    .allowMainThreadQueries()
                    .createFromAsset(DB_NAME) // Load từ assets nếu database chưa tồn tại
                    .fallbackToDestructiveMigration() // Added to handle schema changes during development
                    .build();
        }
        return instance;
    }

    public abstract FoodsDAO foodsDAO();
}

package com.example.nhom33.DataEntity; // Hãy sửa lại package cho đúng với thư mục của bạn

import androidx.room.ColumnInfo;
import androidx.room.Entity;
import androidx.room.ForeignKey;
import androidx.room.PrimaryKey;

@Entity(
        tableName = "Foods",
        foreignKeys = {
                @ForeignKey(
                        entity = CategoriesEntity.class, // Tên lớp Entity của bảng Categories
                        parentColumns = "category_id",
                        childColumns = "category_id",
                        onDelete = ForeignKey.CASCADE // Hoặc NO_ACTION tùy theo logic của bạn
                )
        }
)
public class FoodsEntity {

    @PrimaryKey(autoGenerate = true)
    @ColumnInfo(name = "food_id")
    private int foodId;

    @ColumnInfo(name = "restaurant_id")
    private int restaurantId;

    @ColumnInfo(name = "category_id")
    private int categoryId;

    @ColumnInfo(name = "food_name")
    private String foodName; // NOT NULL trong SQLite tương đương không được để null ở Java

    @ColumnInfo(name = "description")
    private String description;

    @ColumnInfo(name = "price")
    private double price; // REAL trong SQLite tương đương với double/float trong Java

    @ColumnInfo(name = "price_sale")
    private Double priceSale; // Dùng kiểu đối tượng Double để có thể nhận giá trị null

    @ColumnInfo(name = "image_url")
    private String imageUrl;

    @ColumnInfo(name = "is_available", defaultValue = "1")
    private int isAvailable; // INTEGER trong SQLite lưu 0 hoặc 1 thay cho boolean

    @ColumnInfo(name = "meal_type", defaultValue = "Cả ngày")
    private String mealType; // Nhận các giá trị 'Sáng', 'Trưa', 'Tối', 'Cả ngày'

    // ================= UAN TRỌNG: CONSTRUCTOR =================
    // Constructor mặc định được Room sử dụng để khởi tạo đối tượng
    public FoodsEntity(int restaurantId, int categoryId, String foodName, String description,
                       double price, Double priceSale, String imageUrl, int isAvailable, String mealType) {
        this.restaurantId = restaurantId;
        this.categoryId = categoryId;
        this.foodName = foodName;
        this.description = description;
        this.price = price;
        this.priceSale = priceSale;
        this.imageUrl = imageUrl;
        this.isAvailable = isAvailable;
        this.mealType = mealType;
    }

    // ================= GETTER VÀ SETTER =================
    // Room bắt buộc phải có Getter/Setter để đọc ghi dữ liệu từ các thuộc tính private

    public int getFoodId() { return foodId; }
    public void setFoodId(int foodId) { this.foodId = foodId; }

    public int getRestaurantId() { return restaurantId; }
    public void setRestaurantId(int restaurantId) { this.restaurantId = restaurantId; }

    public int getCategoryId() { return categoryId; }
    public void setCategoryId(int categoryId) { this.categoryId = categoryId; }

    public String getFoodName() { return foodName; }
    public void setFoodName(String foodName) { this.foodName = foodName; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public double getPrice() { return price; }
    public void setPrice(double price) { this.price = price; }

    public Double getPriceSale() { return priceSale; }
    public void setPriceSale(Double priceSale) { this.priceSale = priceSale; }

    public String getImageUrl() { return imageUrl; }
    public void setImageUrl(String imageUrl) { this.imageUrl = imageUrl; }

    public int getIsAvailable() { return isAvailable; }
    public void setIsAvailable(int isAvailable) { this.isAvailable = isAvailable; }

    public String getMealType() { return mealType; }
    public void setMealType(String mealType) { this.mealType = mealType; }
}

package com.example.nhom33.DataEntity; // Hãy sửa lại package cho đúng với thư mục của bạn

import androidx.room.ColumnInfo;
import androidx.room.Entity;
import androidx.room.ForeignKey;
import androidx.room.Ignore;
import androidx.room.PrimaryKey;

@Entity(
        tableName = "Foods",
        foreignKeys = {
                @ForeignKey(
                        entity = CategoriesEntity.class, // Tên lớp Entity của bảng Categories
                        parentColumns = "category_id",
                        childColumns = "category_id",
                        onDelete = ForeignKey.CASCADE // Hoặc NO_ACTION tùy theo logic của bạn
                )
        }
)
public class FoodsEntity {

    @PrimaryKey(autoGenerate = true)
    @ColumnInfo(name = "food_id")
    private int foodId;

    @Ignore
    @ColumnInfo(name = "restaurant_id")
    private int restaurantId;

    @ColumnInfo(name = "category_id")
    private int categoryId;

    @ColumnInfo(name = "food_name")
    private String foodName; // NOT NULL trong SQLite tương đương không được để null ở Java

    @ColumnInfo(name = "description")
    private String description;

    @ColumnInfo(name = "price")
    private double price; // REAL trong SQLite tương đương với double/float trong Java

    @Ignore
    @ColumnInfo(name = "price_sale")
    private Double priceSale; // Dùng kiểu đối tượng Double để có thể nhận giá trị null

    @ColumnInfo(name = "image_url")
    private String imageUrl;

    @Ignore
    @ColumnInfo(name = "is_available", defaultValue = "1")
    private int isAvailable; // INTEGER trong SQLite lưu 0 hoặc 1 thay cho boolean

    @ColumnInfo(name = "meal_type", defaultValue = "Cả ngày")
    private String mealType; // Nhận các giá trị 'Sáng', 'Trưa', 'Tối', 'Cả ngày'

    // ================= UAN TRỌNG: CONSTRUCTOR =================
    // Constructor mặc định được Room sử dụng để khởi tạo đối tượng
    // No-arg constructor required by Room when it can't use the param constructor
    public FoodsEntity() {
    }

    public FoodsEntity(int restaurantId, int categoryId, String foodName, String description,
                       double price, Double priceSale, String imageUrl, int isAvailable, String mealType) {
        this.restaurantId = restaurantId;
        this.categoryId = categoryId;
        this.foodName = foodName;
        this.description = description;
        this.price = price;
        this.priceSale = priceSale;
        this.imageUrl = imageUrl;
        this.isAvailable = isAvailable;
        this.mealType = mealType;
    }

    // ================= GETTER VÀ SETTER =================
    // Room bắt buộc phải có Getter/Setter để đọc ghi dữ liệu từ các thuộc tính private

    public int getFoodId() { return foodId; }
    public void setFoodId(int foodId) { this.foodId = foodId; }

    public int getRestaurantId() { return restaurantId; }
    public void setRestaurantId(int restaurantId) { this.restaurantId = restaurantId; }

    public int getCategoryId() { return categoryId; }
    public void setCategoryId(int categoryId) { this.categoryId = categoryId; }

    public String getFoodName() { return foodName; }
    public void setFoodName(String foodName) { this.foodName = foodName; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public double getPrice() { return price; }
    public void setPrice(double price) { this.price = price; }

    public Double getPriceSale() { return priceSale; }
    public void setPriceSale(Double priceSale) { this.priceSale = priceSale; }

    public String getImageUrl() { return imageUrl; }
    public void setImageUrl(String imageUrl) { this.imageUrl = imageUrl; }

    public int getIsAvailable() { return isAvailable; }
    public void setIsAvailable(int isAvailable) { this.isAvailable = isAvailable; }

    public String getMealType() { return mealType; }
    public void setMealType(String mealType) { this.mealType = mealType; }
}
